/**
 * Test data for the journey components: the contract examples of `packages/contracts`
 * (generated by the backend), plus stage variants derived from them. Test-only — never
 * imported by application code.
 */
import { readFileSync } from "node:fs";
import { resolve } from "node:path";
import { vi } from "vitest";
import type { UseJourneyResult } from "@/hooks/useJourney";
import type { Booking, Itinerary, Journey, TravelFile } from "@/types/journey";

// Vitest runs from apps/web; the shared contracts live two levels up.
const example = <T>(name: string): T =>
  JSON.parse(readFileSync(resolve(process.cwd(), "../../packages/contracts/examples", name), "utf8")) as T;

/** Stage `adjustments`: Carcassonne, two activities, six adjustments of four kinds. */
export const adjustmentsJourney = example<Journey>("journey_adjustments.json");
/** Stage `booked`: one itinerary, booking confirmed, one accepted adjustment. */
export const bookedJourney = example<Journey>("journey_booked.json");
export const travelFile = example<TravelFile>("travel_file.json");

export const itinerary = bookedJourney.itineraries[0] as Itinerary;
export const booking = bookedJourney.booking as Booking;
export const SIMULATION_NOTICE = bookedJourney.notices[0] as string;

const variant = (label: string, id: string): Itinerary => ({ ...itinerary, id, label });
export const threeItineraries: Itinerary[] = [itinerary, variant("Retour anticipé", "iti_early"), variant("Départ décalé", "iti_late")];

const base: Journey = {
  ...bookedJourney,
  accepted_adjustments: [],
  selected_destination_id: null,
  selected_activity_ids: [],
  itineraries: [],
  selected_itinerary_id: null,
  booking: null,
};

export const destinationsJourney: Journey = {
  ...base,
  stage: "destinations",
  message: "Voici des destinations adaptées à votre thème. Choisissez une destination et vos activités.",
};

export const itinerariesJourney: Journey = {
  ...base,
  stage: "itineraries",
  message: "3 itinéraires possibles. Choisissez celui qui vous convient.",
  selected_destination_id: "carcassonne",
  selected_activity_ids: ["carcassonne-1", "carcassonne-2"],
  itineraries: threeItineraries,
};

export const noMatchJourney: Journey = {
  ...base,
  stage: "no_match",
  message:
    "Aucun itinéraire n'a été trouvé pour ce choix, même avec des ajustements raisonnables. Choisissez une autre destination ou modifiez votre demande.",
  selected_destination_id: "carcassonne",
};

export const reviewJourney: Journey = {
  ...itinerariesJourney,
  stage: "review",
  message:
    "Vérifiez une dernière fois l'itinéraire avant d'envoyer la demande de réservation. Rien n'est réservé tant que vous n'avez pas envoyé la demande.",
  selected_itinerary_id: itinerary.id,
};

export const pendingJourney: Journey = {
  ...reviewJourney,
  stage: "booking_pending",
  message: "Demande envoyée au service de réservation. En attente de confirmation.",
  booking: { ...booking, status: "pending", message: "Demande envoyée au service de réservation. En attente de confirmation." },
};

export const refusedJourney: Journey = {
  ...reviewJourney,
  stage: "booking_refused",
  message: "La réservation n'a pas été confirmée. Voici d'autres itinéraires possibles ; vous pouvez aussi modifier votre demande.",
  booking: {
    ...booking,
    status: "refused",
    message: "La demande n'a pas pu être confirmée (simulation : plus de places pour ce groupe).",
  },
  alternatives: threeItineraries.slice(1),
};

export const closedJourney: Journey = {
  ...bookedJourney,
  stage: "closed",
  message: "Merci pour votre retour d'expérience.",
  feedback: { rating: 4, comment: "Très bien organisé." },
};

/** A `useJourney` result with spies for every action; override what the test needs. */
export function journeyState(overrides: Partial<UseJourneyResult> = {}): UseJourneyResult {
  const ok = () => vi.fn(async () => true);
  return {
    journey: null,
    travelFile: null,
    status: "ready",
    pending: null,
    error: null,
    start: ok(),
    chooseDestination: ok(),
    acceptAdjustment: ok(),
    chooseItinerary: ok(),
    submitBooking: ok(),
    checkBooking: ok(),
    loadTravelFile: ok(),
    giveFeedback: ok(),
    dismissError: vi.fn(),
    ...overrides,
  };
}
